#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    std::string maxSumOfSquares(int num, int sum) {
        if (sum < 1 || sum > 9 * num) {
            return "";
        }

        std::vector<int> digits(num, 0);
        int rem_sum = sum;

        for (int i = 0; i < num; ++i) {
            int take = std::min(9, rem_sum - (num - 1 - i));
            digits[i] = take;
            rem_sum -= take;
        }

        std::string result = "";
        for (int d : digits) {
            result += std::to_string(d);
        }
        return result;
    }
};
